 static class Sprite extends TextureAtlasSprite {Sprite(String n){super(n);setIconWidth(16);setIconHeight(16);initSprite(128,128,32,48,false);}}
 static void geometry(ObjMesh mesh,TextureAtlasSprite sprite,IBakedModel model){
  List<float[]> vertices=new ArrayList<>();for(ObjMesh.Part part:mesh.parts)if(part.name.equals("Gen"))for(ObjMesh.Face face:part.faces)for(int i=0;i<face.corners.size();i++){ObjMesh.Corner c=face.corners.get(i);float[] v={(float)(.5D+c.position.x),c.position.y,(float)(.5D+c.position.z),sprite.getInterpolatedU(c.uv.x*16D),sprite.getInterpolatedV(c.uv.y*16D)};vertices.add(v);if(i%3==2&&face.corners.size()==3)vertices.add(v);}
  List<BakedQuad> quads=model.getQuads(null,null,0);verify(!quads.isEmpty()&&quads.size()==vertices.size()/4,"original Gen stream count");
  for(int i=0;i<quads.size();i++){BakedQuad q=quads.get(i);verify(q.getSprite()==sprite&&q.getFormat().equals(DefaultVertexFormats.ITEM),"native format/material");int[] raw=q.getVertexData();for(int j=0;j<4;j++){float[] v=vertices.get(i*4+j);int n=j*7;for(int k=0;k<3;k++)equal(Float.intBitsToFloat(raw[n+k]),v[k],"source position");verify(raw[n+3]==-1,"original white color");equal(Float.intBitsToFloat(raw[n+4]),v[3],"source U");equal(Float.intBitsToFloat(raw[n+5]),v[4],"source V");}}
  verify(model.isGui3d()&&!model.isBuiltInRenderer()&&!model.isAmbientOcclusion(),"original inventory lighting");for(EnumFacing f:EnumFacing.values())verify(model.getQuads(null,f,0).isEmpty(),"unculled stream");
 }
