 static class Recorder implements MeshModel {final MeshModel real;final List<String> names=new ArrayList<>();final List<float[]> transforms=new ArrayList<>();boolean fail;Recorder(MeshModel m){real=m;}public ObjMesh getMesh(){return real.getMesh();}public List<String> getPartNames(){return real.getPartNames();}public void renderAll(){throw new AssertionError();}public void renderOnly(String... n){throw new AssertionError();}public void renderAllExcept(String... n){throw new AssertionError();}public void renderPart(String n){names.add(n);transforms.add(matrix());if(fail){GlStateManager.pushMatrix();GlStateManager.translate(9,8,7);GlStateManager.disableLighting();throw new IllegalStateException("mesh failure");}real.renderPart(n);}}
